# R/helpers.R
# Small utilities: parse user concentration entries, format CIs, classify
# severity, build the citable sentence.

parse_concentrations <- function(txt) {
    if (is.null(txt) || !nzchar(txt)) return(numeric(0))
    raw <- unlist(strsplit(txt, "[,;\\s]+", perl = TRUE))
    raw <- raw[nzchar(raw)]
    v <- suppressWarnings(as.numeric(raw))
    v <- v[!is.na(v) & v >= 0]
    unique(sort(v))
}

fmt_pct <- function(x, digits = 1L) {
    if (length(x) == 0L) return(character(0))
    paste0(formatC(100 * x, format = "f", digits = digits), "%")
}

fmt_ci <- function(lo, hi, digits = 2L, scale = c("identity", "pct")) {
    scale <- match.arg(scale)
    if (scale == "pct") {
        sprintf("[%s, %s]", fmt_pct(lo, digits), fmt_pct(hi, digits))
    } else {
        sprintf("[%s, %s]",
                formatC(lo, format = "g", digits = digits),
                formatC(hi, format = "g", digits = digits))
    }
}

fmt_num <- function(x, digits = 3L) {
    formatC(x, format = "g", digits = digits)
}

# Severity bands on the proportion-effect scale (signed effect = 1 - p_pred /
# p_max_median). Returns a translation key for i18n.
severity_key <- function(effect) {
    if (is.na(effect)) return("sev_none")
    if (effect <  0.05) return("sev_none")
    if (effect <  0.20) return("sev_mild")
    if (effect <  0.50) return("sev_moderate")
    if (effect <  0.80) return("sev_severe")
    "sev_near"
}

severity_css <- function(key) {
    c(sev_none = "severity-badge severity-none",
      sev_mild = "severity-badge severity-mild",
      sev_moderate = "severity-badge severity-moderate",
      sev_severe = "severity-badge severity-severe",
      sev_near   = "severity-badge severity-near")[key]
}

# Micrograph filename to display for a given severity key. Two canonical
# images per endpoint: control (intact) and stressed (abnormal).
micrograph_path <- function(severity, endpoint) {
    if (endpoint == "fert") {
        if (severity %in% c("sev_none", "sev_mild")) "micrographs/egg_control.png"
        else "micrographs/egg_unfertilised.png"
    } else {
        if (severity %in% c("sev_none", "sev_mild")) "micrographs/larva_control.png"
        else "micrographs/larva_blocked.png"
    }
}

# Build the citable sentence for a single (population, sunscreen, endpoint,
# concentration) prediction. Language-aware via t_().
citable_sentence <- function(conc, sunscreen, population, endpoint,
                             pred_median, ci_lo, ci_hi, p_threshold,
                             threshold_pct, lang = "en") {
    endpoint_lbl <- if (lang == "es") {
        if (endpoint == "fert") "la fecundación" else "el desarrollo larvario"
    } else {
        if (endpoint == "fert") "fertilisation" else "larval development"
    }
    pop_lbl <- if (lang == "es") c(Malaga = "Málaga", Cadiz = "Cádiz")[population] else population
    if (lang == "es") {
        sprintf(paste("A %.3g mg/L de la crema solar %s,",
                      "%s de P. lividus en %s",
                      "se predice una respuesta media de %s",
                      "(intervalo creíble 95%%: %s a %s);",
                      "P(efecto > %d%%) = %.2f.",
                      "Fuente: Aranda-Quirós et al. (2026), seaurchin."),
                conc, sunscreen, endpoint_lbl, pop_lbl,
                fmt_pct(pred_median),
                fmt_pct(ci_lo), fmt_pct(ci_hi),
                as.integer(threshold_pct), p_threshold)
    } else {
        sprintf(paste("At %.3g mg/L of sunscreen %s,",
                      "%s of P. lividus from %s",
                      "is predicted to reach a median response of %s",
                      "(95%% credible interval: %s to %s);",
                      "P(effect > %d%%) = %.2f.",
                      "Source: Aranda-Quirós et al. (2026), seaurchin."),
                conc, sunscreen, endpoint_lbl, pop_lbl,
                fmt_pct(pred_median),
                fmt_pct(ci_lo), fmt_pct(ci_hi),
                as.integer(threshold_pct), p_threshold)
    }
}

# Cached gzipped-CSV reader. base::read.csv on a gzfile connection avoids the
# vroom binary dependency that breaks under the current R toolchain.
read_csv_gz <- function(path) {
    con <- gzfile(path, open = "rt", encoding = "UTF-8")
    on.exit(close(con), add = TRUE)
    utils::read.csv(con, stringsAsFactors = FALSE, check.names = FALSE)
}

read_csv_plain <- function(path) {
    utils::read.csv(path, stringsAsFactors = FALSE, check.names = FALSE,
                    encoding = "UTF-8")
}

// www/clipboard.js
// One-click "copy citable sentence" handler. Receives the sentence from the R
// server and writes it to the system clipboard, with a brief visual ack on
// the originating button if the element id is supplied.

(function () {
    Shiny.addCustomMessageHandler('copy_to_clipboard', function (msg) {
        if (!navigator.clipboard) {
            console.warn('seaurchin: clipboard API not available');
            return;
        }
        navigator.clipboard.writeText(msg.text).then(function () {
            if (msg.button_id) {
                var btn = document.getElementById(msg.button_id);
                if (!btn) return;
                var orig = btn.innerHTML;
                btn.innerHTML = '✓ ' + (msg.ack || 'Copied');
                btn.classList.add('btn-success');
                setTimeout(function () {
                    btn.innerHTML = orig;
                    btn.classList.remove('btn-success');
                }, 1600);
            }
        });
    });
})();

/* www/custom.css
