// www/download.js
// Client-side Blob handlers for PNG and CSV downloads, routed from the R
// server via Shiny.addCustomMessageHandler. Required for Shinylive because
// downloadHandler is unavailable in the WebAssembly runtime.

(function () {
    function triggerDownload(blob, filename) {
        var url = URL.createObjectURL(blob);
        var a = document.createElement('a');
        a.href = url;
        a.download = filename;
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
        URL.revokeObjectURL(url);
    }

    Shiny.addCustomMessageHandler('download_csv', function (msg) {
        var blob = new Blob([msg.content], { type: 'text/csv;charset=utf-8;' });
        triggerDownload(blob, msg.filename);
    });

    Shiny.addCustomMessageHandler('download_png', function (msg) {
        var byteChars = atob(msg.content);
        var bytes = new Uint8Array(byteChars.length);
        for (var i = 0; i < byteChars.length; i++) {
            bytes[i] = byteChars.charCodeAt(i);
        }
        var blob = new Blob([bytes], { type: 'image/png' });
        triggerDownload(blob, msg.filename);
    });
})();

